globalThis.__snapbackHandlers = { "createPostMutation": (async (ctx, args) => ({
    _id: await ctx.db.insert('posts', { ownerId: ctx.auth.userId, body: args.body }),
  })) };

globalThis.__snapbackHandlers = { "sendMessageMutation": (async (ctx, args) => ({
    _id: await ctx.db.insert('messages', {
      ownerId: ctx.auth.userId,
      conversationId: args.conversationId,
      text: args.text,
    }),
  })) };
